uth_example:
candidates = [
    "def avg(xs): return sum(xs) / len(xs)",
    "def avg(xs): return sum(xs) // len(xs)",
    "def avg(xs): return sum(xs) / len(xs) if xs else 0.0",
]
tests = [([2, 4], 3.0), ([1, 2], 1.5), ([], 0.0)]

def verifier(source):                       # the reward: fraction of tests passed
    scope = {}
    exec(source, scope)
    passed = 0
    for args, want in tests:
        try:
            passed += scope["avg"](args) == want
        except ZeroDivisionError:
            pass
    return passed / len(tests)

scores = [round(verifier(c), 2) for c in candidates]
best = max(range(len(candidates)), key=lambda i: scores[i])
print("scores:", scores)
print("winner:", candidates[best])
